//! Generated by zmodu saas — orders smoke test (in-memory sqlite)
const std = @import("std");
const zigmodu = @import("zigmodu");
const model = @import("model.zig");
const persistence = @import("persistence.zig");
const service = @import("service.zig");
test "orders persistence + CrudService round-trip" {
    const allocator = std.testing.allocator;
    var client = zigmodu.data.Client.init(allocator, std.testing.io, .{ .driver = .sqlite, .sqlite_path = ":memory:" });
    defer client.deinit();
    try client.connect();
    _ = try client.exec("CREATE TABLE orders (id INTEGER PRIMARY KEY AUTOINCREMENT, org_id INTEGER NOT NULL, customer TEXT NOT NULL, amount INTEGER NOT NULL, status TEXT NOT NULL, notes TEXT NOT NULL, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL)", &.{});

    var backend = zigmodu.data.SqlxBackend{ .allocator = allocator, .client = &client };
    var persist = persistence.OrdersPersistence.init(&backend);
    var svc = service.OrdersService.init(&persist);

    var bus = zigmodu.TypedEventBus(zigmodu.data.CrudEvent(model.Orders)).init(allocator);
    defer bus.deinit();
    svc.crud.setEventBus(&bus);
    const id = try svc.crud.create(.{
        .org_id = 1,
        .customer = "alice",
        .amount = 100,
        .status = "alice",
        .notes = "alice",
    });
    try std.testing.expect(id > 0);
    try std.testing.expectEqual(@as(u64, 1), bus.publishedCount());

    var items = try svc.crud.list(1, 1, 10, null);
    defer items.deinit(allocator);
    try std.testing.expectEqual(@as(usize, 1), items.items.len);

    const got = (try svc.crud.get(allocator, 1, id)).?;
    defer zigmodu.data.sqlx.freeScanned(allocator, model.Orders, got);
    try std.testing.expectEqual(id, got.id);

    var updated = got;
    updated.org_id = 1;
    try svc.crud.update(updated, 1);
    try std.testing.expectEqual(@as(u64, 2), bus.publishedCount());

    try svc.crud.delete(1, id);
    try std.testing.expectEqual(@as(u64, 3), bus.publishedCount());

    const tx_id = try svc.transact(i64, struct {
        fn f(tx: *zigmodu.data.sqlx.Transaction) zigmodu.ZigModuError!i64 {
            _ = tx;
            return 42;
        }
    }.f);
    try std.testing.expectEqual(@as(i64, 42), tx_id);
}
